import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getCar } from '../services/carService';
import LoanCalculator from '../components/LoanCalculator';
import TestDriveForm from '../components/TestDriveForm';  // ✅ правильный путь

const CarDetailPage = () => {
  const { id } = useParams();
  const [car, setCar] = useState(null);

  useEffect(() => {
    getCar(id).then(res => setCar(res.data)).catch(console.error);
  }, [id]);

  if (!car) return <div>Загрузка...</div>;
  return (
    <div style={{ maxWidth: 800, margin: '0 auto', padding: 20 }}>
      <h1>{car.brand} {car.model} ({car.year})</h1>
      <img src={car.image_url} alt={car.model} style={{ width: '100%', maxHeight: 400, objectFit: 'cover' }} />
      <p>{car.description}</p>
      <p>Цена: <strong>{car.price.toLocaleString()} ₽</strong></p>
      <LoanCalculator carId={car.id} carPrice={car.price} />
      <TestDriveForm carId={car.id} />
    </div>
  );
};

export default CarDetailPage;
